use ndarray::{Array1,Array2,Axis};
pub struct Linear{pub weight:Array2<f32>,pub bias:Array1<f32>,pub has_bias:bool,pub grad_weight:Array2<f32>,pub grad_bias:Array1<f32>,pub qat_bits:u8}
impl Linear{pub fn new(in_features:usize,out_features:usize)->Self{Self::new_with_bias(in_features,out_features,true,0)}pub fn new_no_bias(in_features:usize,out_features:usize)->Self{Self::new_with_bias(in_features,out_features,false,0)}pub fn new_with_qat(in_features:usize,out_features:usize,has_bias:bool,bits:u8)->Self{Self::new_with_bias(in_features,out_features,has_bias,bits)}fn new_with_bias(in_features:usize,out_features:usize,has_bias:bool,bits:u8)->Self{assert!(in_features>0&&out_features>0);assert!(matches!(bits,0|2|3|4|8));let scale=(2.0/in_features as f32).sqrt();let mut weight=Array2::<f32>::zeros((out_features,in_features));for o in 0..out_features{for i in 0..in_features{let value=(((o*in_features+i)*1103515245+12345)%100000)as f32;weight[[o,i]]=(value/50000.0-1.0)*scale}}Self{weight,bias:Array1::zeros(out_features),has_bias,grad_weight:Array2::zeros((out_features,in_features)),grad_bias:Array1::zeros(out_features),qat_bits:bits}}pub fn with_qat_bits(mut self,bits:u8)->Self{assert!(matches!(bits,0|2|3|4|8));self.qat_bits=bits;self}pub fn from_weights(weight:Array2<f32>,bias:Array1<f32>)->Self{assert_eq!(weight.nrows(),bias.len());Self{grad_weight:Array2::zeros(weight.raw_dim()),grad_bias:Array1::zeros(bias.raw_dim()),weight,bias,has_bias:true,qat_bits:0}}pub fn from_weight(weight:Array2<f32>)->Self{let out_features=weight.nrows();Self{grad_weight:Array2::zeros(weight.raw_dim()),grad_bias:Array1::zeros(out_features),weight,bias:Array1::zeros(out_features),has_bias:false,qat_bits:0}}pub fn forward(&self,input:&Array2<f32>)->Array2<f32>{assert_eq!(input.ncols(),self.weight.ncols());let mut output=match self.qat_bits{2|4|8=>{let bits=crate::qat::Bits::from_bits(self.qat_bits).unwrap();let(w,s)=crate::qat::quantize_weight(&self.weight,bits);let values=crate::gpu::packed_linear(input.as_slice().unwrap(),&w,&s,input.nrows(),self.weight.ncols(),self.weight.nrows(),self.qat_bits).unwrap();Array2::from_shape_vec((input.nrows(),self.weight.nrows()),values).unwrap()},_=>input.dot(&self.weight.t())};if self.has_bias{output+=&self.bias}output}pub fn backward(&mut self,input:&Array2<f32>,grad_output:&Array2<f32>)->Array2<f32>{assert_eq!(input.ncols(),self.weight.ncols());assert_eq!(grad_output.nrows(),input.nrows());assert_eq!(grad_output.ncols(),self.weight.nrows());self.grad_weight+=&grad_output.t().dot(input);if self.has_bias{self.grad_bias+=&grad_output.sum_axis(Axis(0))}grad_output.dot(&self.weight)}pub fn zero_grad(&mut self){self.grad_weight.fill(0.0);self.grad_bias.fill(0.0)}pub fn parameter_count(&self)->usize{self.weight.len()+if self.has_bias{self.bias.len()}else{0}}}
#[cfg(test)]mod tests{use super::*;use ndarray::array;#[test]fn forward_matches_matrix_multiplication(){let layer=Linear::from_weights(array![[1.0,2.0],[3.0,4.0]],array![0.5,-0.5]);let output=layer.forward(&array![[2.0,3.0]]);assert_eq!(output,array![[8.5,16.5]])}#[test]fn no_bias_has_only_weight_parameters(){let layer=Linear::new_no_bias(2,3);assert!(!layer.has_bias);assert_eq!(layer.parameter_count(),6)}#[test]fn backward_accumulates_gradients(){let mut layer=Linear::from_weights(array![[1.0,2.0],[3.0,4.0]],array![0.0,0.0]);let grad_input=layer.backward(&array![[2.0,3.0]],&array![[5.0,7.0]]);assert_eq!(layer.grad_weight,array![[10.0,15.0],[14.0,21.0]]);assert_eq!(layer.grad_bias,array![5.0,7.0]);assert_eq!(grad_input,array![[26.0,38.0]])}#[test]fn packed_forward_preserves_shape(){let layer=Linear::new_with_qat(8,4,true,4);let output=layer.forward(&Array2::ones((3,8)));assert_eq!(output.dim(),(3,4));}}
